import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.DTwTvi8b.js";const p=JSON.parse('{"title":"0009 程序与本机配置分开存放，按版本目录并存","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0009-versioned-install-layout.md","filePath":"reference/adr/0009-versioned-install-layout.md","lastUpdated":null}'),l={name:"reference/adr/0009-versioned-install-layout.md"};function o(s,a,n,d,c,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<div><h1 id="_0009-程序与本机配置分开存放-按版本目录并存" tabindex="-1">0009 程序与本机配置分开存放，按版本目录并存 <a class="header-anchor" href="#_0009-程序与本机配置分开存放-按版本目录并存" aria-label="Permalink to &quot;0009 程序与本机配置分开存放，按版本目录并存&quot;">​</a></h1><ul><li>状态：已采纳</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>脚本版的配置放在程序目录里，升级要手工保留配置；运行中的流水线依赖程序文件，直接覆盖有风险；也无法快速回滚。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><p>程序放在 ~/tools/req-kit/versions/&lt;版本&gt;/，本机配置放在 ~/.req-kit/。在哪个版本目录运行 install.mjs，就启用哪个版本。状态文件带格式版本，可迁移。</p><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>升级不动配置；运行中的流水线按旧版本跑完；回滚是一条命令。旧版本目录需要定期清理（install.mjs --prune 会列出）。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0009-versioned-install-layout.md">docs/adr/0009-versioned-install-layout.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0009-versioned-install-layout.md">在 GitHub 上编辑</a></p>',2)])])}const _=e(l,[["render",o]]);export{p as __pageData,_ as default};
